/**
 * Server-only access to the dedicated "GESAwards Bootcamp 2027 RSVP" Airtable
 * base. Never import this from a client component: it reads a secret token.
 *
 * Security model
 * - Each invited startup has one row in "Bootcamp 2027 RSVP" holding a random
 *   secret token (generated by scripts/bootcamp-rsvp-tokens.mjs).
 * - The personal link /bootcamp/rsvp/<token> is the only way to read or change
 *   that row. No token → no access; one token only reaches its own row.
 * - The PAT in BOOTCAMP_RSVP_AIRTABLE_TOKEN should be scoped to this base only
 *   (data.records:read + data.records:write). It never reaches the browser.
 */

const API = "https://api.airtable.com/v0";

// Field IDs are used instead of names so renaming a column in Airtable does
// not break the site.
export const RSVP_TABLE = "tblcEXj21fkvbM6am";
export const ATTENDEES_TABLE = "tblOhmfv1eVW3xeRc";

const F = {
  startup: "fldHcinbHfekbzigF",
  token: "flddSKn74a8hx6nbE",
  attending: "fldjGuBsq8vMuWddQ",
  repName: "fld9GMRHUEmvgAFVU",
  repEmail: "fld7VAsWwlXyQ0MgJ",
  country: "fld80BiwkNKNt58Pm",
  attendeeCount: "fldewNTdPvSHPjclx",
  comments: "fldtcSobtV2t76Lsi",
  lastSubmitted: "fldKSANczrEfpOX0G",
  submissionCount: "fldyLw6Ii5IHAGh8H",
  attendeesLink: "fldIph1gDFSpfUgMz",
} as const;

const A = {
  name: "fldTECOByEYz0hLPb",
  email: "fldaK22nOu5NHP7Aj",
  dietary: "fldrtofKJr5OHrIz4",
  startupLink: "fld4F51mKPitvQXfL",
} as const;

export type AttendingAnswer = "Yes" | "No" | "Not sure yet";

export interface Attendee {
  name: string;
  email: string;
  dietary: string;
}

export interface Invitation {
  recordId: string;
  startup: string;
  attending: AttendingAnswer | null;
  repName: string;
  repEmail: string;
  country: string;
  comments: string;
  attendees: Attendee[];
  submissionCount: number;
}

export interface RsvpInput {
  attending: AttendingAnswer;
  repName: string;
  repEmail: string;
  country: string;
  comments: string;
  attendees: Attendee[];
}

/** Tokens are base64url, 32+ chars. Anything else is rejected before any API call. */
export const TOKEN_RE = /^[A-Za-z0-9_-]{32,64}$/;

export class RsvpConfigError extends Error {}

function config() {
  const token = process.env.BOOTCAMP_RSVP_AIRTABLE_TOKEN;
  const baseId = process.env.BOOTCAMP_RSVP_BASE_ID ?? "appkgKBfdmjHBG8JR";
  if (!token) throw new RsvpConfigError("BOOTCAMP_RSVP_AIRTABLE_TOKEN is not set");
  return { token, baseId };
}

async function airtable(path: string, init: RequestInit = {}) {
  const { token, baseId } = config();
  const res = await fetch(`${API}/${baseId}/${path}`, {
    ...init,
    cache: "no-store",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
      ...init.headers,
    },
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Airtable ${res.status} on ${init.method ?? "GET"} ${path}: ${body}`);
  }
  return res.json();
}

type Fields = Record<string, unknown>;
const str = (v: unknown) => (typeof v === "string" ? v : "");

export async function getInvitationByToken(token: string): Promise<Invitation | null> {
  if (!TOKEN_RE.test(token)) return null;
  // TOKEN_RE guarantees no quotes/braces, so the formula cannot be injected.
  const formula = encodeURIComponent(`{${F.token}}='${token}'`);
  const data = await airtable(
    `${RSVP_TABLE}?filterByFormula=${formula}&maxRecords=2&returnFieldsByFieldId=true`
  );
  const records = data.records as { id: string; fields: Fields }[];
  // Exactly one match required. A duplicated token is treated as invalid
  // rather than guessing which startup it belongs to.
  if (records.length !== 1) return null;
  const { id, fields } = records[0];
  if (str(fields[F.token]) !== token) return null;

  const linkIds = (fields[F.attendeesLink] as string[] | undefined) ?? [];
  const attendees = await getAttendees(linkIds);

  const attending = str(fields[F.attending]);
  return {
    recordId: id,
    startup: str(fields[F.startup]),
    attending:
      attending === "Yes" || attending === "No" || attending === "Not sure yet"
        ? attending
        : null,
    repName: str(fields[F.repName]),
    repEmail: str(fields[F.repEmail]),
    country: str(fields[F.country]),
    comments: str(fields[F.comments]),
    attendees,
    submissionCount: Number(fields[F.submissionCount] ?? 0) || 0,
  };
}

async function getAttendees(ids: string[]): Promise<Attendee[]> {
  if (!ids.length) return [];
  const formula = encodeURIComponent(
    `OR(${ids.map((id) => `RECORD_ID()='${id}'`).join(",")})`
  );
  const data = await airtable(
    `${ATTENDEES_TABLE}?filterByFormula=${formula}&returnFieldsByFieldId=true`
  );
  const byId = new Map(
    (data.records as { id: string; fields: Fields }[]).map((r) => [r.id, r.fields])
  );
  // Preserve the order stored on the RSVP row.
  return ids
    .map((id) => byId.get(id))
    .filter((f): f is Fields => !!f)
    .map((f) => ({ name: str(f[A.name]), email: str(f[A.email]), dietary: str(f[A.dietary]) }));
}

/**
 * Upserts the RSVP for an existing invitation. The startup row is updated in
 * place (never duplicated) and its attendee list is replaced with the new one.
 */
export async function saveRsvp(token: string, input: RsvpInput): Promise<Invitation | null> {
  const invitation = await getInvitationByToken(token);
  if (!invitation) return null;

  const data = await airtable(
    `${RSVP_TABLE}/${invitation.recordId}?returnFieldsByFieldId=true`
  );
  const oldAttendeeIds = ((data.fields as Fields)[F.attendeesLink] as string[] | undefined) ?? [];

  // 1. Create the new attendee rows, linked to this startup (max 10 per call).
  const attendees = input.attending === "No" ? [] : input.attendees;
  for (let i = 0; i < attendees.length; i += 10) {
    await airtable(ATTENDEES_TABLE, {
      method: "POST",
      body: JSON.stringify({
        records: attendees.slice(i, i + 10).map((a) => ({
          fields: {
            [A.name]: a.name,
            [A.email]: a.email,
            [A.dietary]: a.dietary,
            [A.startupLink]: [invitation.recordId],
          },
        })),
      }),
    });
  }

  // 2. Update the startup row.
  await airtable(`${RSVP_TABLE}/${invitation.recordId}`, {
    method: "PATCH",
    body: JSON.stringify({
      fields: {
        [F.attending]: input.attending,
        [F.repName]: input.repName,
        [F.repEmail]: input.repEmail,
        [F.country]: input.country,
        [F.attendeeCount]: attendees.length,
        [F.comments]: input.comments,
        [F.lastSubmitted]: new Date().toISOString(),
        [F.submissionCount]: invitation.submissionCount + 1,
      },
    }),
  });

  // 3. Remove the previous attendee rows only after the new ones exist, so a
  //    failure part-way never leaves the startup with no attendees.
  for (let i = 0; i < oldAttendeeIds.length; i += 10) {
    const qs = oldAttendeeIds
      .slice(i, i + 10)
      .map((id) => `records[]=${id}`)
      .join("&");
    await airtable(`${ATTENDEES_TABLE}?${qs}`, { method: "DELETE" });
  }

  return getInvitationByToken(token);
}
